using CustomCodeFramework.Core.Pagination;using CustomCodeFramework.Postgres.EntityFramework.Repositories;using Dhole.Content.Application.Abstractions.Repositories;using Dhole.Content.Contracts.Media;using Dhole.Content.Domain.Media.Entities;using Dhole.Content.Persistence.DbContexts;using Microsoft.EntityFrameworkCore;namespace Dhole.Content.Persistence.Repositories;
public sealed class MediaReferenceRepository(ServiceDbContext db):EfRepository<MediaReference,Guid>(db),IMediaReferenceRepository
{public Task<bool> ExistsByStorageFileIdAsync(Guid storageFileId,CancellationToken ct=default)=>db.MediaReferences.AnyAsync(x=>x.StorageFileId==storageFileId&&!x.IsDeleted,ct);public async Task<PagedResult<MediaDto>> GetPagedAsync(PageRequest page,string? search=null,string? contentType=null,CancellationToken ct=default){var q=db.MediaReferences.AsNoTracking().Where(x=>!x.IsDeleted);if(!string.IsNullOrWhiteSpace(search)){var v=search.Trim().ToLower();q=q.Where(x=>x.FileName.ToLower().Contains(v)||(x.AltText!=null&&x.AltText.ToLower().Contains(v))||(x.Caption!=null&&x.Caption.ToLower().Contains(v)));}if(!string.IsNullOrWhiteSpace(contentType)){var t=contentType.Trim().ToLower();q=q.Where(x=>x.ContentType.ToLower().StartsWith(t));}var total=await q.CountAsync(ct);var items=await q.OrderByDescending(x=>x.CreatedAtUtc).Skip(page.Skip).Take(page.PageSize).Select(x=>new MediaDto(x.Id,x.StorageFileId,x.FileName,x.ContentType,x.AltText,x.Caption,x.MetadataJson,x.CreatedAtUtc,x.UpdatedAtUtc)).ToListAsync(ct);return PagedResult<MediaDto>.Create(items,page.PageNumber,page.PageSize,total);}}
